fn solve(x: i32) -> i32 {
    // Convert to string to extract digit and length
    let s = x.to_string();
    let k = s.len() as i32;
    // All characters are the same, so just take the first one
    let d = s.chars().next().unwrap().to_digit(10).unwrap() as i32;

    // For each digit < d, we have lengths 1+2+3+4 = 10 presses each
    // Then for digit d, we press lengths 1..=k, which sums to k*(k+1)/2
    (d - 1) * 10 + k * (k + 1) / 2
}

